50: void BattleProcessor::engageIntoBattle(PlayerColor player)
51: {
52: 	// Release only after the complete server request and all battle queries.
53: 	if(player.isValidPlayer())
54: 		gameHandler->pendingBattleBarriers.insert(player);
55: 	//notify interfaces
56: 	PlayerBlocked pb;
57: 	pb.player = player;
58: 	pb.reason = PlayerBlocked::UPCOMING_BATTLE;
59: 	pb.startOrEnd = PlayerBlocked::BLOCKADE_STARTED;
60: 	gameHandler->sendAndApply(pb);
61: }

21: void QueriesProcessor::popQuery(PlayerColor player, QueryPtr query)
22: {
23: 	LOG_TRACE_PARAMS(logGlobal, "player='%s', query='%s'", player % query);
24: 	if(topQuery(player) != query)
25: 	{
26: 		logGlobal->trace("Cannot remove, not a top!");
27: 		return;
28: 	}
29: 
30: 	const auto idx = static_cast<size_t>(player.getNum());
31: 	assert(query);
32: 
33: 	auto & stack = queries.at(idx);
34: 	stack.pop_back();
35: 	auto nextQuery = topQuery(player);
36: 
37: 	query->onRemoval(player);
38: 
39: 	//Exposure on query below happens only if removal didn't trigger any new query
40: 	if(nextQuery && nextQuery == topQuery(player))
41: 		nextQuery->onExposure(query);
42: 
43: 	if(queriesStackListener)
44: 		queriesStackListener->onQueryStackChanged(player);
45: 
46: 	if(!topQuery(player))
47: 		gameHandler.checkVictoryLossConditionsForPlayer(player);
48: }

100: void CBattleQuery::onRemoval(PlayerColor color)
