426: void BattleResultProcessor::battleFinalize(const BattleID & battleID, const BattleResult & result)
427: {
428: 	LOG_TRACE(logGlobal);
429: 
430: 	assert(finishingBattles.count(battleID) != 0);
431: 	if(finishingBattles.count(battleID) == 0)
432: 		return;
433: 
434: 	auto & finishingBattle = finishingBattles[battleID];
435: 
436: 	finishingBattle->remainingBattleQueriesCount--;
437: 	logGlobal->trace("Decremented gameHandler->queries count to %d", finishingBattle->remainingBattleQueriesCount);
438: 
439: 	if (finishingBattle->remainingBattleQueriesCount > 0)
440: 		//Battle results will be handled when all battle gameHandler->queries are closed
441: 		return;
442: 
443: 	//TODO consider if we really want it to work like above. ATM each player as unblocked as soon as possible
444: 	// but the battle consequences are applied after final player is unblocked. Hard to abuse...
445: 	// Still, it looks like a hole.
446: 
447: 	const auto battle = std::find_if(gameHandler->gameState().currentBattles.begin(), gameHandler->gameState().currentBattles.end(),
448: 		[battleID](const auto & desiredBattle)
449: 		{
450: 			return desiredBattle->battleID == battleID;
451: 		});
452: 	assert(battle != gameHandler->gameState().currentBattles.end());

681: 	//notify all players that battle has ended after all consequences are applied
682: 	BattleEnded ended;
683: 	ended.battleID = battleID;
684: 	ended.victor = finishingBattle->victor;
685: 	ended.loser = finishingBattle->loser;
686: 	gameHandler->sendAndApply(ended);
687: 
688: 	//handle victory/loss of engaged players
689: 	gameHandler->checkVictoryLossConditions({finishingBattle->loser, finishingBattle->victor});
690: 
691: 	finishingBattles.erase(battleID);
692: 	battleResults.erase(battleID);
693: }

387: void CDirectorAI::advanceTurn()
