476: void CDirectorAI::playerBlocked(int reason, bool start)
477: {
478: 	if(reason == PlayerBlocked::UPCOMING_BATTLE)
479: 	{
480: 		battleBusy = start;
481: 		traceState(start ? "native_battle_blocked" : "native_battle_ready");
482: 		if(!start)
483: 			advanceTurn();
484: 	}
485: 	if(reason == PlayerBlocked::ONGOING_MOVEMENT)
486: 	{
487: 		movementBusy = start;
488: 		traceState(start ? "native_movement_blocked" : "native_movement_unblocked");
489: 		if(!start)
490: 			advanceTurn();
491: 	}
492: }
